@Reader.reader_handler
     : forall (Env : Type) (E MN : Type -> Type),
       Env -> forall X : Type, Sum.sum1 (Reader.readerE Env) E X -> PTreeDefinition.ptree E MN X

@Reader.reader_ask_returns
     : forall (Env : Type) (E MN : Type -> Type) (env : Env),
       @Reader.reader_handler Env E MN env Env
         (@Sum.inl1 (Reader.readerE Env) E Env (@Reader.Ask Env)) =
       {|
         PTreeDefinition._observe :=
           @PTreeDefinition.RetF E MN Env (PTreeDefinition.ptree E MN Env) env
       |}

@Reader.reader_residual_forwards
     : forall (Env : Type) (E MN : Type -> Type) (X : Type) (env : Env) (e : E X),
       @Reader.reader_handler Env E MN env X (@Sum.inr1 (Reader.readerE Env) E X e) =
       {|
         PTreeDefinition._observe :=
           @PTreeDefinition.VisF E MN X (PTreeDefinition.ptree E MN X) X e
             (fun x : X =>
              {|
                PTreeDefinition._observe :=
                  @PTreeDefinition.RetF E MN X (PTreeDefinition.ptree E MN X) x
              |})
       |}

@Exception.observe_run_exception
     : forall (Err : Type) (E MN : Type -> Type) (A : Type)
         (t : PTreeDefinition.ptree (Sum.sum1 (Exception.exceptE Err) E) MN A),
       @PTreeDefinition.observe E MN (Err + A) (@Exception.run_exception Err E MN A t) =
       match @PTreeDefinition.observe (Sum.sum1 (Exception.exceptE Err) E) MN A t with
       | @PTreeDefinition.RetF _ _ _ _ a =>
           @PTreeDefinition.RetF E MN (Err + A) (PTreeDefinition.ptree E MN (Err + A))
             (@inr Err A a)
       | @PTreeDefinition.TauF _ _ _ _ u =>
           @PTreeDefinition.TauF E MN (Err + A) (PTreeDefinition.ptree E MN (Err + A))
             (@Exception.run_exception Err E MN A u)
       | @PTreeDefinition.VisF _ _ _ _ X (@Sum.inl1 _ _ _ ex) _ =>
           @PTreeDefinition.RetF E MN (Err + A) (PTreeDefinition.ptree E MN (Err + A))
             (@inl Err A (@Exception.exception_value Err X ex))
       | @PTreeDefinition.VisF _ _ _ _ X (@Sum.inr1 _ _ _ fe) k =>
           @PTreeDefinition.VisF E MN (Err + A) (PTreeDefinition.ptree E MN (Err + A)) X fe
             (fun x : X => @Exception.run_exception Err E MN A (k x))
       | @PTreeDefinition.ProbF _ _ _ _ X mu k =>
           @PTreeDefinition.ProbF E MN (Err + A) (PTreeDefinition.ptree E MN (Err + A)) X mu
             (fun x : X => @Exception.run_exception Err E MN A (k x))
       end

