@ExceptionFacts.run_exception_ret
     : forall (Err : Type) (E MN : Type -> Type) (A : Type) (a : A),
       @PStruct.pstruct E MN (Err + A) (Err + A) (@eq (Err + A))
         (@Exception.run_exception Err E MN A
            {|
              PTreeDefinition._observe :=
                @PTreeDefinition.RetF (Sum.sum1 (Exception.exceptE Err) E) MN A
                  (PTreeDefinition.ptree (Sum.sum1 (Exception.exceptE Err) E) MN A) a
            |})
         {|
           PTreeDefinition._observe :=
             @PTreeDefinition.RetF E MN (Err + A) (PTreeDefinition.ptree E MN (Err + A))
               (@inr Err A a)
         |}

@ExceptionFacts.run_exception_throw
     : forall (Err : Type) (E MN : Type -> Type) (A : Type) (e : Err),
       @PStruct.pstruct E MN (Err + A) (Err + A) (@eq (Err + A))
         (@Exception.run_exception Err E MN A
            {|
              PTreeDefinition._observe :=
                @PTreeDefinition.VisF (Sum.sum1 (Exception.exceptE Err) E) MN A
                  (PTreeDefinition.ptree (Sum.sum1 (Exception.exceptE Err) E) MN A) Empty_set
                  (@Sum.inl1 (Exception.exceptE Err) E Empty_set (@Exception.Throw Err e))
                  (fun v : Empty_set =>
                   match
                     v return (PTreeDefinition.ptree (Sum.sum1 (Exception.exceptE Err) E) MN A)
                   with
                   end)
            |})
         {|
           PTreeDefinition._observe :=
             @PTreeDefinition.RetF E MN (Err + A) (PTreeDefinition.ptree E MN (Err + A))
               (@inl Err A e)
         |}

