@ExceptionFacts.exception_hitting_approx
     : forall (Err : Type) (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       forall (A : Type) (n : nat)
         (t : PTreeDefinition.ptree (Sum.sum1 (Exception.exceptE Err) E) MN A),
       @BindScheduling.equiv MF FI FO (UnifiedFrontier.stable_head E MN (Err + A))
         (@PTreeKernel.ptree_hitting_approx E MN MF FI MX FO (Err + A) n
            (@PTreeDefinition.observe E MN (Err + A) (@Exception.run_exception Err E MN A t)))
         (@Measure.sem_bind MF FI
            (UnifiedFrontier.stable_head (Sum.sum1 (Exception.exceptE Err) E) MN A)
            (UnifiedFrontier.stable_head E MN (Err + A))
            (@PTreeKernel.ptree_hitting_approx (Sum.sum1 (Exception.exceptE Err) E) MN MF FI MX FO
               A n (@PTreeDefinition.observe (Sum.sum1 (Exception.exceptE Err) E) MN A t))
            (fun h : UnifiedFrontier.stable_head (Sum.sum1 (Exception.exceptE Err) E) MN A =>
             @Measure.sem_ret MF FI (UnifiedFrontier.stable_head E MN (Err + A))
               (@ExceptionFacts.exception_head Err E MN A h)))

