         (front : MF (UnifiedFrontier.stable_head (Sum.sum1 (Exception.exceptE Err) E) MN A)),
       @PTreeKernel.ptree_stable_hitting (Sum.sum1 (Exception.exceptE Err) E) MN MF FI MX FO A
         (@PTreeDefinition.observe (Sum.sum1 (Exception.exceptE Err) E) MN A t) front ->
       @PTreeKernel.ptree_stable_hitting E MN MF FI MX FO (Err + A)
         (@PTreeDefinition.observe E MN (Err + A) (@Exception.run_exception Err E MN A t))
         (@Measure.sem_bind MF FI
